/**
 * A {@link Loader} for processing UNIX-style A.out executables
 * <p>
 * This style was also used by UNIX-like systems such as SunOS, BSD, and VxWorks, as well as some 
 * early distributions of Linux. Although there do exist implementations of A.out with 64-bit and \
 * GNU extensions, this loader does not currently support them.
 *
 * @see <a href="https://wiki.osdev.org/A.out">OSDev.org A.out</a>
 * @see <a href="https://man.freebsd.org/cgi/man.cgi?a.out(5)">FreeBSD manpage</a>
 */
public class UnixAoutLoader : AbstractProgramWrapperLoader {

	public static string UNIX_AOUT_NAME = "UNIX A.out";

	public static readonly string OPTION_NAME_BASE_ADDR = "Base Address";

	public static readonly string OPTION_NAME_TEXT_ADDR = "Text Load Address";

	/* @Override */
	public Collection<LoadSpec> findSupportedLoadSpecs(ByteProvider provider)
    {
		List<LoadSpec> loadSpecs = new();

		// Attempt to parse the header as both little- and big-endian.
		// It is likely that only one of these will produce sensible values.
		UnixAoutHeader hdrBE = new UnixAoutHeader(provider, false);
		UnixAoutHeader hdrLE = new UnixAoutHeader(provider, true);
		bool beValid = false;

		if (hdrBE.isValid()) {
			string lang = hdrBE.getLanguageSpec();
			string comp = hdrBE.getCompilerSpec();
			loadSpecs.add(new LoadSpec(this, 0, new LanguageCompilerSpecPair(lang, comp), true));
			beValid = true;
		}
		if (hdrLE.isValid()) {
			string lang = hdrLE.getLanguageSpec();
			string comp = hdrLE.getCompilerSpec();
			loadSpecs
					.add(new LoadSpec(this, 0, new LanguageCompilerSpecPair(lang, comp), !beValid));
		}

		return loadSpecs;
	}

	/* @Override */
	protected void load(Program program, ImporterSettings settings)
    {
		bool isLittleEndian = !program.getLanguage().isBigEndian();
		UnixAoutHeader header = new UnixAoutHeader(settings.provider(), isLittleEndian,
			getAddrOption(settings.options(), OPTION_NAME_TEXT_ADDR));

		UnixAoutProgramLoader loader =
			new UnixAoutProgramLoader(program, header, settings.monitor(), settings.log());
		loader.loadAout(getBaseAddrOffset(settings.options()));
	}

	/* @Override */
	public string validateOptions(ByteProvider provider, LoadSpec loadSpec, List<Option> options,
			Program program) {
		Address baseAddr = null;

		foreach (Option option in options) {
			string optName = option.getName();
			try {
				if (optName.equals(OPTION_NAME_BASE_ADDR)) {
					baseAddr = (Address) option.getValue();
				}
			}
			catch (Exception e) {
				if (e is OptionException) {
					return e.getMessage();
				}
				return "Invalid value for " + optName + " - " + option.getValue();
			}
		}
		if (baseAddr == null) {
			return "Invalid base address";
		}

		return base.validateOptions(provider, loadSpec, options, program);
	}

	/* @Override */
	public List<Option> getDefaultOptions(ByteProvider provider, LoadSpec loadSpec,
			DomainObject domainObject, bool loadIntoProgram, bool mirrorFsLayout) {
		Address baseAddr = null;

		if (domainObject is Program) {
			Program program = (Program) domainObject;
			AddressFactory addressFactory = program.getAddressFactory();
			if (addressFactory != null) {
				AddressSpace defaultAddressSpace = addressFactory.getDefaultAddressSpace();
				if (defaultAddressSpace != null) {
					baseAddr = defaultAddressSpace.getAddress(0);
				}
			}
		}

		List<Option> list = new List<Option>();
		list.add(Option.newAddress(OPTION_NAME_BASE_ADDR)
				.value(baseAddr)
				.commandLineArgument(createArg("-baseAddr"))
				.build());

		try {
			Language language = loadSpec.getLanguageCompilerSpec().getLanguage();
			UnixAoutHeader header = new UnixAoutHeader(provider, !language.isBigEndian());
			list.add(Option.newAddress(OPTION_NAME_TEXT_ADDR)
					.value(language.getDefaultSpace().getAddress(header.getTextAddr()))
					.commandLineArgument(createArg("-textAddr"))
					.build());
		}
		catch (Exception e) {
			Msg.error(this, "Error while generating A.out import options", e);
		}

		list.addAll(base.getDefaultOptions(provider, loadSpec, domainObject, loadIntoProgram,
			mirrorFsLayout));
		return list;
	}

	/* @Override */
	public string getName() {
		return UNIX_AOUT_NAME;
	}

	/**
	 * Retrieves the Address offset given in the "Base Address" option.
	 * Returns 0 if the option could not be found or contains an invalid value.
	 */
	private long getBaseAddrOffset(List<Option> options) {
		Long offset = getAddrOption(options, OPTION_NAME_BASE_ADDR);
		return offset != null ? offset : 0;
	}

	/**
	 * Retrieves the offset of the Address given in the named option, or null if the option is
	 * absent or holds no value.
	 */
	private static Long getAddrOption(List<Option> options, string name) {
		Address addr = OptionUtils.getOption(name, options, (Address) null);
		return addr != null ? addr.getOffset() : null;
	}
}
